const OPERATOR_NAMESPACE: &str = "dpf-hcp-provisioner-system";
const TARGET_NAMESPACE: &str = "dpf-operator-system";
const X86_OVN_IMAGE: &str = "quay.io/openshift-release-dev/ocp-v4.0-art-dev@sha256:aaa111";
const ARM64_OVN_IMAGE: &str = "quay.io/openshift-release-dev/ocp-v4.0-art-dev@sha256:bbb222";

#[derive(Debug, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
struct Step {
    error: String,
    reader_calls: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    rules: Vec<Rule>,
    steps: Vec<Step>,
    objects: BTreeMap<String, String>,
}

fn fixture(name: &str) -> Fixture {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

fn fixed_time() -> Time {
    Time("2025-01-01T00:00:00Z".parse().unwrap())
}

