fn meta(name: &str, namespace: &str) -> ObjectMeta {
    ObjectMeta {
        name: Some(name.into()),
        namespace: (!namespace.is_empty()).then(|| namespace.to_string()),
        ..Default::default()
    }
}

fn scheme() -> Scheme {
    Scheme::new()
        .register::<provisioningv1alpha1::DPFHCPProvisioner>()
        .register::<provisioningv1alpha1::DPFHCPProvisionerConfig>()
        .register::<dpuservicev1alpha1::DPUServiceTemplate>()
        .register::<dpuservicev1alpha1::DPUDeployment>()
        .register::<operatorv1alpha1::DPFOperatorConfig>()
        .register::<configv1::ClusterVersion>()
        .register::<DaemonSet>()
        .register::<Secret>()
        .register::<ConfigMap>()
}

fn dpf_operator_config(version: &str) -> InitObject {
    let mut c = operatorv1alpha1::DPFOperatorConfig {
        metadata: meta("dpfoperatorconfig", "dpf-operator-system"),
        ..Default::default()
    };
    c.status.version = Some(version.into());
    obj(&c)
}

fn cluster_version_obj(image: &str, version: &str) -> configv1::ClusterVersion {
    let mut cv = configv1::ClusterVersion {
        metadata: meta("version", ""),
        ..Default::default()
    };
    cv.spec.cluster_id = "test-cluster".into();
    cv.status.desired.image = image.into();
    cv.status.desired.version = version.into();
    cv
}

fn pull_secret() -> InitObject {
    obj(&Secret {
        metadata: meta("pull-secret", "openshift-config"),
        data: Some(BTreeMap::from([(
            ".dockerconfigjson".to_string(),
            ByteString(br#"{"auths":{}}"#.to_vec()),
        )])),
        type_: Some("kubernetes.io/dockerconfigjson".into()),
        ..Default::default()
    })
}

fn ovn_daemon_set(
    image: &str,
    generation: i64,
    desired: i32,
    updated: i32,
    available: i32,
) -> DaemonSet {
    let labels = BTreeMap::from([("app".to_string(), "ovnkube".to_string())]);
    let mut ds = DaemonSet {
        metadata: meta("ovnkube-node-dpu-host", "openshift-ovn-kubernetes"),
        spec: Some(DaemonSetSpec {
            selector: LabelSelector {
                match_labels: Some(labels.clone()),
                ..Default::default()
            },
            template: PodTemplateSpec {
                metadata: Some(ObjectMeta {
                    labels: Some(labels),
                    ..Default::default()
                }),
                spec: Some(PodSpec {
                    containers: vec![
                        Container {
                            name: "sidecar".into(),
                            image: Some("quay.io/other:v1".into()),
                            ..Default::default()
                        },
                        Container {
                            name: "ovnkube-controller".into(),
                            image: Some(image.into()),
                            ..Default::default()
                        },
                    ],
                    ..Default::default()
                }),
            },
            ..Default::default()
        }),
        ..Default::default()
    };
    if generation != 0 {
        ds.metadata.generation = Some(generation);
        ds.status = Some(DaemonSetStatus {
            observed_generation: Some(generation),
            desired_number_scheduled: desired,
            updated_number_scheduled: Some(updated),
            number_available: Some(available),
            ..Default::default()
        });
    }
    ds
}

fn overrides_config_map(data: &str) -> InitObject {
    obj(&ConfigMap {
        metadata: meta("dpuservicetemplate-overrides", OPERATOR_NAMESPACE),
        data: Some(BTreeMap::from([(
            "overrides.json".to_string(),
            data.to_string(),
        )])),
        ..Default::default()
    })
}

fn labels(pairs: &[(&str, &str)]) -> Option<BTreeMap<String, String>> {
    Some(
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect(),
    )
}

fn managed() -> Option<BTreeMap<String, String>> {
    labels(&[(common::LABEL_MANAGED_BY, "true")])
}

fn template(
    name: &str,
    labels: Option<BTreeMap<String, String>>,
    annotations: Option<BTreeMap<String, String>>,
    repo_url: &str,
    version: &str,
    values: &str,
    deleting: bool,
) -> InitObject {
    let mut t = dpuservicev1alpha1::DPUServiceTemplate {
        metadata: meta(name, TARGET_NAMESPACE),
        ..Default::default()
    };
    t.metadata.labels = labels;
    t.metadata.annotations = annotations;
    t.spec.deployment_service_name = name.into();
    t.spec.helm_chart.source.repo_url = repo_url.into();
    t.spec.helm_chart.source.version = version.into();
    t.spec.helm_chart.source.chart = "old-chart".into();
    if !values.is_empty() {
        t.spec.helm_chart.values = Some(Json::from_slice(values.as_bytes()).unwrap());
    }
    if deleting {
        t.metadata.deletion_timestamp = Some(fixed_time());
        t.metadata.finalizers = Some(vec![
            dpuservicev1alpha1::DPU_SERVICE_TEMPLATE_FINALIZER.into(),
        ]);
    }
    obj(&t)
}

fn source_annotation(image: &str) -> Option<BTreeMap<String, String>> {
    labels(&[(ANNOTATION_SOURCE_OVN_IMAGE, image)])
}

fn operator_config_cr(manage: bool) -> InitObject {
    let mut c = provisioningv1alpha1::DPFHCPProvisionerConfig {
        metadata: meta(provisioningv1alpha1::DEFAULT_CONFIG_NAME, ""),
        ..Default::default()
    };
    c.spec.manage_dpu_service_templates = manage;
    c.spec.dpu_services_image_pull_secret = "cfg-pull-secret".into();
    obj(&c)
}

fn provisioner(name: &str, dpu_cluster_ns: &str, dd_name: &str, deleting: bool) -> InitObject {
    let mut p = provisioningv1alpha1::DPFHCPProvisioner {
        metadata: meta(name, "default"),
        ..Default::default()
    };
    p.spec.dpu_cluster_ref = provisioningv1alpha1::DPUClusterReference {
        name: "cluster".into(),
        namespace: dpu_cluster_ns.into(),
        ..Default::default()
    };
    if !dd_name.is_empty() {
        p.spec.dpu_deployment_ref = Some(provisioningv1alpha1::DPUDeploymentReference {
            name: dd_name.into(),
            namespace: TARGET_NAMESPACE.into(),
            ..Default::default()
        });
    }
    if deleting {
        p.metadata.deletion_timestamp = Some(fixed_time());
        p.metadata.finalizers = Some(vec!["provisioning.dpu.hcp.io/finalizer".into()]);
    }
    obj(&p)
}

fn dpu_deployment(name: &str, deleting: bool) -> InitObject {
    let mut d = dpuservicev1alpha1::DPUDeployment {
        metadata: meta(name, TARGET_NAMESPACE),
        ..Default::default()
    };
    d.spec.dpus.bfb = Some("bfb".into());
    d.spec.dpus.flavor = Some("flavor".into());
    if deleting {
        d.metadata.deletion_timestamp = Some(fixed_time());
        d.metadata.finalizers = Some(vec![dpuservicev1alpha1::DPU_DEPLOYMENT_FINALIZER.into()]);
    }
    obj(&d)
}

fn release(host: &str, tag: &str) -> String {
    format!("{host}/ocp/release:{tag}")
}

/// Objects of `prereqs(host, tag, version)`: [DPFOperatorConfig, ClusterVersion, pull secret, DaemonSet].
fn prereqs(host: &str, tag: &str, version: &str) -> Vec<InitObject> {
    vec![
        dpf_operator_config("26.4.0-f314aa17"),
        obj(&cluster_version_obj(&release(host, tag), version)),
        pull_secret(),
        obj(&ovn_daemon_set(X86_OVN_IMAGE, 0, 0, 0, 0)),
    ]
}

fn with(mut objs: Vec<InitObject>, more: Vec<InitObject>) -> Vec<InitObject> {
    objs.extend(more);
    objs
}

// ---------------------------------------------------------------------------------------------
// Fake release reader & scenario environment
// ---------------------------------------------------------------------------------------------

struct FakeReader {
    image: Mutex<String>,
    err: Option<String>,
    calls: Mutex<Vec<String>>,
}

impl FakeReader {
    fn image(image: &str) -> Arc<Self> {
        Arc::new(Self {
            image: Mutex::new(image.into()),
            err: None,
            calls: Mutex::new(vec![]),
        })
    }
    fn err(err: &str) -> Arc<Self> {
        Arc::new(Self {
            image: Mutex::new(String::new()),
            err: Some(err.into()),
            calls: Mutex::new(vec![]),
        })
    }
}

#[async_trait]
impl ReleaseImageReader for FakeReader {
    async fn get_component_image(
        &self,
        _ctx: &Ctx,
        release_image_ref: &str,
        component_name: &str,
        _keychain: Arc<dyn Keychain>,
    ) -> ctrlrt::Result<String> {
        self.calls
            .lock()
            .unwrap()
            .push(format!("{release_image_ref} {component_name}"));
        match &self.err {
            Some(e) => Err(anyhow::anyhow!(e.clone())),
            None => Ok(self.image.lock().unwrap().clone()),
        }
    }
}

struct Env {
    reg: RulesRegistry,
    c: Client,
    reader: Arc<FakeReader>,
    mgr: Arc<DPUServiceTemplateManager>,
    steps: Vec<Step>,
}

impl Env {
    fn host(&self) -> String {
        self.reg.host.clone()
    }

    fn record(&mut self, res: ctrlrt::Result<()>) {
        let error = match res {
            Ok(()) => String::new(),
            Err(e) => self.reg.norm(&e.to_string()),
        };
        let calls = std::mem::take(&mut *self.reader.calls.lock().unwrap());
        self.steps.push(Step {
            error,
            reader_calls: calls.iter().map(|c| self.reg.norm(c)).collect(),
        });
    }

    async fn ensure(&mut self, cfg: &OperatorConfig) {
        let res = self
            .mgr
            .ensure_templates(&Ctx::background(), TARGET_NAMESPACE, cfg)
            .await;
        self.record(res);
    }

    async fn delete(&mut self) {
        let res = self
            .mgr
            .delete_templates(&Ctx::background(), TARGET_NAMESPACE)
            .await;
        self.record(res);
    }

    async fn reconcile(&mut self) {
        let r = DPUServiceTemplateReconciler::new(self.c.clone(), self.mgr.clone());
        let res = r
            .reconcile(&Ctx::background(), ObjectKey::new("", TARGET_NAMESPACE))
            .await
            .map(|_| ());
        self.record(res);
    }

    async fn replace_cluster_version(
        &self,
        old: configv1::ClusterVersion,
        mut new: configv1::ClusterVersion,
    ) {
        self.c.delete(&old).await.unwrap();
        self.c.create(&mut new).await.unwrap();
    }

    async fn replace_daemon_set(&self, old: DaemonSet, mut new: DaemonSet) {
        self.c.delete(&old).await.unwrap();
        self.c.create(&mut new).await.unwrap();
    }
}

/// Run one scenario: start the rules registry from the fixture, build the fake client from
/// `objects(host)`, run `steps`, and compare with the fixture.
async fn run<O, S>(name: &str, reader: Arc<FakeReader>, objects: O, steps: S)
where
    O: FnOnce(&str) -> Vec<InitObject>,
    S: AsyncFnOnce(&mut Env),
{
    let fx = fixture(name);
    let reg = RulesRegistry::start(fx.rules.clone()).await;
    let objs = objects(&reg.host);
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(objs)
        .with_status_subresource::<operatorv1alpha1::DPFOperatorConfig>()
        .build();
    let mgr = Arc::new(DPUServiceTemplateManager::new(
        c.clone(),
        c.clone(),
        reader.clone(),
        OPERATOR_NAMESPACE,
    ));
    let mut env = Env {
        reg,
        c,
        reader,
        mgr,
        steps: vec![],
    };
    steps(&mut env).await;

    assert_eq!(env.steps, fx.steps, "{name}: steps");

    for (tname, want) in &fx.objects {
        let got = env
            .c
            .get::<dpuservicev1alpha1::DPUServiceTemplate>(&ObjectKey::new(TARGET_NAMESPACE, tname))
            .await
            .ok()
            .map(|mut t| {
                // The fake client stamps metav1.Now() on Delete.
                if t.metadata.deletion_timestamp.is_some() {
                    t.metadata.deletion_timestamp = Some(fixed_time());
                }
                t
            })
            .map(|t| {
                env.reg
                    .norm(&String::from_utf8(gocompat::json::to_go_json(&t).unwrap()).unwrap())
            })
            .unwrap_or_default();
        assert_eq!(&got, want, "{name}: object {tname}");
    }
}

fn no_cfg() -> OperatorConfig {
    OperatorConfig::default()
}

