// ---------------------------------------------------------------------------------------------
// RemoteReleaseImageReader
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct ReaderCase {
    name: String,
    rules: Vec<Rule>,
    #[serde(rename = "ref")]
    ref_: String,
    component: String,
    result: String,
    error: String,
}

#[tokio::test]
async fn golden_remote_release_image_reader() {
    let path = format!(
        "{}/tests/fixtures/release_reader.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let cases: Vec<ReaderCase> =
        serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert!(!cases.is_empty());
    for rc in cases {
        let reg = RulesRegistry::start(rc.rules.clone()).await;
        let r = rc.ref_.replace("REGISTRY", &reg.host);
        let kc: Arc<dyn Keychain> = Arc::new(MultiKeychain::new(vec![]));
        let res = RemoteReleaseImageReader
            .get_component_image(&Ctx::background(), &r, &rc.component, kc)
            .await;
        let (result, error) = match res {
            Ok(v) => (v, String::new()),
            Err(e) => (String::new(), reg.norm(&e.to_string())),
        };
        assert_eq!(result, rc.result, "{}: result", rc.name);
        assert_eq!(error, rc.error, "{}: error", rc.name);
    }
}
